                    if keyword in k:
                        return  v

            aa = self.mm_projector.load_state_dict(get_w(mm_projector_weights, 'mm_projector'), strict=False)
            print("projctor")
            print(aa)

            aa = self.vision_tower.load_state_dict(get_w(mm_projector_weights, 'vision_tower'), strict=False)
            print("vision_tower.unexpected_keys")
            print(aa.unexpected_keys)

        else:
            self.random_initialize_model(self.mm_projector)


    def random_initialize_model(self, model, mean=0.0, std=0.02):
        """
        随机初始化给定模型的所有参数。

        参数:
        - model (nn.Module): 要初始化的PyTorch模型实例。
        - mean (float): 权重初始化的均值，默认为0.0。
        - std (float): 权重初始化的标准差，默认为0.02。
        """
        for name, param in model.named_parameters():
            if 'weight' in name:
                # 对于权重，使用正态分布进行初始化
                init.normal_(param.data, mean=mean, std=std)
            elif 'bias' in name:
                # 对于偏置项，默认初始化为0，也可以根据需要调整
                init.constant_(param.data, val=0)

def eval_model(args):
    # Model
    disable_torch_init()

    model_name = get_model_name_from_path(args.model_path)
    tokenizer, model, image_processor, context_len = load_pretrained_model(
        args.model_path, args.model_base, model_name
    )

    qs = args.query
    image_token_se = DEFAULT_IM_START_TOKEN + DEFAULT_IMAGE_TOKEN + DEFAULT_IM_END_TOKEN
    if IMAGE_PLACEHOLDER in qs:
        if model.config.mm_use_im_start_end:
            qs = re.sub(IMAGE_PLACEHOLDER, image_token_se, qs)
        else:
            qs = re.sub(IMAGE_PLACEHOLDER, DEFAULT_IMAGE_TOKEN, qs)
    else:
        if model.config.mm_use_im_start_end:
            qs = image_token_se + "\n" + qs
        else:
            qs = DEFAULT_IMAGE_TOKEN + "\n" + qs

    if "llama-2" in model_name.lower():
        conv_mode = "llava_llama_2"
    elif "mistral" in model_name.lower():
        conv_mode = "mistral_instruct"
    elif "v1.6-34b" in model_name.lower():
        conv_mode = "chatml_direct"
    elif "v1" in model_name.lower():
        conv_mode = "llava_v1"
    elif "mpt" in model_name.lower():
        conv_mode = "mpt"
    else:
        conv_mode = "llava_v0"

    if args.conv_mode is not None and conv_mode != args.conv_mode:
        print(
            "[WARNING] the auto inferred conversation mode is {}, while `--conv-mode` is {}, using {}".format(
                conv_mode, args.conv_mode, args.conv_mode
            )
        )
    else:
        args.conv_mode = conv_mode

    conv = conv_templates[args.conv_mode].copy()
    conv.append_message(conv.roles[0], qs)
    conv.append_message(conv.roles[1], None)
    prompt = conv.get_prompt()

    image_files = image_parser(args)
    images = load_images(image_files)
    image_sizes = [x.size for x in images]
    images_tensor = process_images(
        images,
        image_processor,
        model.config
    ).to(model.device, dtype=torch.float16)

    input_ids = (
        tokenizer_image_token(prompt, tokenizer, IMAGE_TOKEN_INDEX, return_tensors="pt")
        .unsqueeze(0)
        .cuda()
    )

    with torch.inference_mode():
        output_ids = model.generate(
            input_ids,
            images=images_tensor,
            image_sizes=image_sizes,
            do_sample=True if args.temperature > 0 else False,
            temperature=args.temperature,
            top_p=args.top_p,
            num_beams=args.num_beams,
            max_new_tokens=args.max_new_tokens,
            use_cache=True,
        )

    outputs = tokenizer.batch_decode(output_ids, skip_special_tokens=True)[0].strip()
    print(outputs)

def get_eval(content: str, max_tokens: int):
    while True:
        try:
            response = openai.ChatCompletion.create(
                model='gpt-4',
                messages=[{
                    'role': 'system',
                    'content': 'You are a helpful and precise assistant for checking the quality of the answer.'
                }, {
                    'role': 'user',
                    'content': content,
                }],
                temperature=0.2,  # TODO: figure out which temperature is best for evaluation
                max_tokens=max_tokens,
            )
            break
        except openai.error.RateLimitError:
            pass
        except Exception as e:
            print(e)
        time.sleep(NUM_SECONDS_TO_SLEEP)

    print('success!')
    return response['choices'][0]['message']['content']

def eval_pred_list(self, pred_list):
    pred_scores = []
    for entry in pred_list:
        anls = max(
            self.get_anls(entry["pred_answer"], gt) for gt in entry["gt_answers"]
        )
        pred_scores.append(anls)

    accuracy = sum(pred_scores) / len(pred_scores)
    return accuracy

def eval_pred_list(self, pred_list):
    # Create reference and hypotheses captions.
    gts = {}
    res = {}
    for idx, entry in enumerate(pred_list):
        gts[idx] = [{"caption": a} for a in entry["gt_answers"]]
        res[idx] = [{"caption": entry["pred_answer"]}]

    gts = self.tokenizer.tokenize(gts)
    res = self.tokenizer.tokenize(res)
    score, _ = self.scorer.compute_score(gts, res)

    bleu4 = score[3]  # score is (Bleu-1, Bleu-2, Bleu-3, Bleu-4)
    return bleu4
